def _format_size(x: int, sig_figs: int=3, hide_zero: bool=False) ->str:
    if hide_zero and x == 0:
        return ""

    if x == 0:
        return "0"

    # Define units
    units = [
        ("", 1),
        ("K", 10**3),
        ("M", 10**6),
        ("G", 10**9),
        ("T", 10**12),
        ("P", 10**15),
    ]

    # Find the appropriate unit
    unit_index = 0
    for i, (unit, threshold) in enumerate(units):
        if x < threshold:
            break
        unit_index = i

    # Use the appropriate unit
    if unit_index == 0:
        # No unit for values less than 1000
        value = float(x)
        unit = ""
    else:
        # Use the previous unit for values >= 1000
        value = x / units[unit_index - 1][1]
        unit = units[unit_index - 1][0]

    # Format to specified significant figures
    if unit:
        # For values with units, format appropriately
        if value >= 1000:
            # Large numbers, use integer format
            return f"{int(value)}{unit}"
        else:
            # Calculate decimal places needed
            if value >= 100:
                decimal_places = max(0, sig_figs - 3)
            elif value >= 10:
                decimal_places = max(0, sig_figs - 2)
            else:
                decimal_places = max(0, sig_figs - 1)

            formatted = f"{value:.{decimal_places}f}".rstrip('0').rstrip('.')
            return f"{formatted}{unit}"
    else:
        # No unit case
        if value >= 1000:
            return str(int(value))
        else:
            if value >= 100:
                decimal_places = max(0, sig_figs - 3)
            elif value >= 10:
                decimal_places = max(0, sig_figs - 2)
            else:
                decimal_places = max(0, sig_figs - 1)

            formatted = f"{value:.{decimal_places}f}".rstrip('0').rstrip('.')
            return formatted
